Generate a standalone C reproducer that triggers this vulnerability:

File: contrib/dbs/xtiff/xtiff.c
Line: 453
Function: GetTIFFHeader
Bug type: divide-by-zero
CWE: CWE-369
Explanation: colormapSize is computed as (1 << tfBitsPerSample). If a crafted TIFF sets BitsPerSample to 0, colormapSize becomes 1 and colormapSize - 1 is 0. The SCALE macro is then invoked as SCALE(i, 0), causing an integer divide-by-zero when initializing dRed/dGreen/dBlue (e.g., at line 453).

Source context:
```c
      413:     dBlue = (double *)malloc(colormapSize * sizeof(double));
      414:     MCHECK(dRed);
      415:     MCHECK(dGreen);
      416:     MCHECK(dBlue);
      417: 
      418:     /*
      419:      * If TIFFTAG_PHOTOMETRIC is not present then assign a reasonable default.
      420:      * The TIFF 5.0 specification doesn't give a default.
      421:      */
      422:     if (!TIFFGetField(tfFile, TIFFTAG_PHOTOMETRIC,
      423:                       &tfPhotometricInterpretation))
      424:     {
      425:         if (tfSamplesPerPixel != 1)
      426:             tfPhotometricInterpretation = PHOTOMETRIC_RGB;
      427:         else if (tfBitsPerSample == 1)
      428:             tfPhotometricInterpretation = PHOTOMETRIC_MINISBLACK;
      429:         else if (TIFFGetField(tfFile, TIFFTAG_COLORMAP, &redMap, &greenMap,
      430:                               &blueMap))
      431:         {
      432:             tfPhotometricInterpretation = PHOTOMETRIC_PALETTE;
      433:             redMap = greenMap = blueMap = NULL;
      434:         }
      435:         else
      436:             tfPhotometricInterpretation = PHOTOMETRIC_MINISBLACK;
      437:     }
      438: 
      439:     /*
      440:      * Given TIFFTAG_PHOTOMETRIC extract or create the response curves.
      441:      */
      442:     switch (tfPhotometricInterpretation)
      443:     {
      444:         case PHOTOMETRIC_RGB:
      445:             redMap = (uint16_t *)malloc(colormapSize * sizeof(uint16_t));
      446:             greenMap = (uint16_t *)malloc(colormapSize * sizeof(uint16_t));
      447:             blueMap = (uint16_t *)malloc(colormapSize * sizeof(uint16_t));
      448:             MCHECK(redMap);
      449:             MCHECK(greenMap);
      450:             MCHECK(blueMap);
      451:             for (i = 0; i < colormapSize; i++)
      452:                 dRed[i] = dGreen[i] = dBlue[i] =
>>>   453:                     (double)SCALE(i, colormapSize - 1);
      454:             break;
      455:         case PHOTOMETRIC_PALETTE:
      456:             if (!TIFFGetField(tfFile, TIFFTAG_COLORMAP, &redMap, &greenMap,
      457:                               &blueMap))
      458:             {
      459:                 redMap = (uint16_t *)malloc(colormapSize * sizeof(uint16_t));
      460:                 greenMap = (uint16_t *)malloc(colormapSize * sizeof(uint16_t));
      461:                 blueMap = (uint16_t *)malloc(colormapSize * sizeof(uint16_t));
      462:                 MCHECK(redMap);
      463:                 MCHECK(greenMap);
      464:                 MCHECK(blueMap);
      465:                 for (i = 0; i < colormapSize; i++)
      466:                     dRed[i] = dGreen[i] = dBlue[i] =
      467:                         (double)SCALE(i, colormapSize - 1);
      468:             }
      469:             else
      470:             {
      471:                 CheckAndCorrectColormap();
      472:                 for (i = 0; i < colormapSize; i++)
      473:                 {
      474:                     dRed[i] = (double)redMap[i];
      475:                     dGreen[i] = (double)greenMap[i];
      476:                     dBlue[i] = (double)blueMap[i];
      477:                 }
      478:             }
      479:             break;
      480:         case PHOTOMETRIC_MINISWHITE:
      481:             redMap = (uint16_t *)malloc(colormapSize * sizeof(uint16_t));
      482:             greenMap = (uint16_t *)malloc(colormapSize * sizeof(uint16_t));
      483:             blueMap = (uint16_t *)malloc(colormapSize * sizeof(uint16_t));
      484:             MCHECK(redMap);
      485:             MCHECK(greenMap);
      486:             MCHECK(blueMap);
      487:             for (i = 0; i < colormapSize; i++)
      488:                 dRed[i] = dGreen[i] = dBlue[i] =
      489:                     (double)SCALE(colormapSize - 1 - i, colormapSize - 1);
      490:             break;
      491:         case PHOTOMETRIC_MINISBLACK:
      492:             redMap = (uint16_t *)malloc(colormapSize * sizeof(uint16_t));
      493:             greenMap = (uint16_t *)malloc(colormapSize * sizeof(uint16_t));
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/libtiff_upstream reproducer.c -L/tmp/libtiff_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/libtiff_upstream
